INSERT INTO news (date, lang, title, text) VALUES
 ('2026-11-14', 'es', 'Grupo de Telegram', 'Nueva opción en Jugar en línea: un código QR al grupo de Telegram de LAIKA 64 para ponerse de acuerdo en los horarios y organizar mejor las partidas. Es solo para eso, no para soporte ni otros temas.'),
 ('2026-11-14', 'en', 'Telegram group', 'New option in Play online: a QR code to the LAIKA 64 Telegram group to agree on times and organize games better. It is only for that, not for support or other topics.'),
 ('2026-11-14', 'pt', 'Grupo do Telegram', 'Nova opção no Jogar online: um código QR para o grupo do Telegram do LAIKA 64 para combinar horários e organizar melhor as partidas. É só para isso, não para suporte nem outros assuntos.'),
 ('2026-11-14', 'fr', 'Groupe Telegram', 'Nouvelle option dans Jouer en ligne : un code QR vers le groupe Telegram de LAIKA 64 pour se mettre d''accord sur les horaires et mieux organiser les parties. Il sert uniquement à cela, pas à l''assistance ni à d''autres sujets.'),
 ('2026-11-14', 'it', 'Gruppo Telegram', 'Nuova opzione in Gioca online: un codice QR per il gruppo Telegram di LAIKA 64 per mettersi d''accordo sugli orari e organizzare meglio le partite. Serve solo a questo, non per l''assistenza o altri argomenti.'),
 ('2026-11-14', 'de', 'Telegram-Gruppe', 'Neu in Online spielen: ein QR-Code zur Telegram-Gruppe von LAIKA 64, um Zeiten abzusprechen und Partien besser zu planen. Sie ist nur dafür da, nicht für Support oder andere Themen.'),
 ('2026-11-14', 'ru', 'Группа в Telegram', 'Новое в Игре по сети: QR-код группы LAIKA 64 в Telegram, чтобы договариваться о времени и лучше организовывать партии. Она только для этого, не для поддержки и других тем.');
